#!/usr/bin/env node
// Inline the shared guess case (dev/guesscase/guess-case.mjs) into every script
// that opts in with a marker block. #785
//
//   // <ST-GUESSCASE> …generated, do not edit… // </ST-GUESSCASE>
//
// The same mechanism as the shared matching (dev/match/sync-match.mjs). The source is one
// self-contained `const mbuGuessCase = (() => { … })();`, which Node imports through the
// exports after it, so the block is the file's own text up to its END-OF-BLOCK line.
//
// Run:  node dev/guesscase/sync-guesscase.mjs      (the pre-commit hook runs it automatically)
// Edit dev/guesscase/guess-case.mjs, NEVER the generated blocks.

import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve, join } from 'node:path';

// Write the file in its own line endings (see sync-match.mjs, #623).
function sameEol(next, src) {
    const crlf = (src.match(/\r\n/g) || []).length, lf = (src.match(/\n/g) || []).length;
    const flat = next.replace(/\r*\n/g, '\n');
    return crlf * 2 > lf ? flat.replace(/\n/g, '\r\n') : flat;
}

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, '..', '..');
const START = '// <ST-GUESSCASE>';
const END = '// </ST-GUESSCASE>';

const file = readFileSync(resolve(HERE, 'guess-case.mjs'), 'utf8').replace(/\r\n/g, '\n');
const from = file.indexOf('const mbuGuessCase = (() => {'), to = file.indexOf('\n// END-OF-BLOCK');
if (from < 0 || to < from) { console.error('✗ guess-case.mjs must hold `const mbuGuessCase = (() => {` … `// END-OF-BLOCK`'); process.exit(1); }
const src = file.slice(from, to);
const lines = [`${START} — generated by dev/guesscase/sync-guesscase.mjs from dev/guesscase/guess-case.mjs — DO NOT EDIT`, ...src.replace(/\r\n/g, '\n').split('\n'), END];

const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const BLOCK_RE = new RegExp(`([ \\t]*)${esc(START)}[^\\n]*\\n[\\s\\S]*?${esc(END)}[^\\n]*`);

function walk(dir, out = []) {
    for (const name of readdirSync(dir)) {
        if (name === 'node_modules' || name === '.git' || name === 'dist' || name === 'string_theory.user.js' || name.endsWith('.pw-profile')) continue;
        const p = join(dir, name);
        if (statSync(p).isDirectory()) walk(p, out);
        else if (/\.js$/.test(name)) out.push(p);
    }
    return out;
}

const updated = [];
let carriers = 0;
for (const file of walk(resolve(ROOT, 'userscripts'))) {
    let text;
    try { text = readFileSync(file, 'utf8'); } catch (e) { continue; }
    if (!text.includes(START)) continue;
    carriers++;
    const indent = (text.match(BLOCK_RE) || [])[1] || '';
    const crlf = text.includes('\r\n');
    const block = lines.map(l => l ? indent + l : l).join(crlf ? '\r\n' : '\n');
    const next = text.replace(BLOCK_RE, () => block);
    const out = sameEol(next, text);
    if (out !== text) { writeFileSync(file, out); updated.push(file.replace(ROOT, '').replace(/\\/g, '/')); }
}
console.log(`✓ guess case synced — ${carriers} file(s) carry the marker, ${updated.length} rewritten:`);
for (const f of updated) console.log('  · ' + f);
if (!carriers) console.log('  (no files carry a // <ST-GUESSCASE> marker yet)');
